import { Authenticator } from '@aws-amplify/ui-react';
import Content from './Content.jsx'
import './App.css';

function App({ apiUrl }) {
    const components = {
        Header() {
            return (
                <div className='d-flex flex-column justify-content-center text-center' style={{ paddingTop: "20%" }}>
                    <p className='h1'>
