            }}
        }}
    }},
    "websocket": {{
        "apiUrl": "wss://{distribution.distribution_domain_name}/ws"
    }}
}}
        """

        frontend_deployment = s3_deployment.BucketDeployment(
            self, "VoicebotFrontendDeployment",

            sources=[
